#include <stdio.h>

#define N 64
static int in[N], out[N];
static int ti = 0, to = 0;

static void push(int v) { in[ti++] = v; }
static int pop(void) {
    if (to == 0)                       /* 出栈为空时，把入栈整体倒入 */
        while (ti > 0) out[to++] = in[--ti];
    return out[--to];
}
static int empty(void) { return ti == 0 && to == 0; }

int main(void) {
    for (int i = 1; i <= 4; i++) push(i);
    printf("入队 1 2 3 4\n");
    printf("出队 -> %d\n", pop());
    push(5);
    printf("入队 5，剩余依次出队:");
    while (!empty()) printf(" %d", pop());
    printf("\n");
    return 0;
}
